{
  "answer": {
    "TCP": {
      "protocol": "Transmission Control Protocol",
      "description": "A reliable connection-oriented protocol used for providing end-to-end communication between applications.",
      "key_features": [
        "Connection-oriented: Ensures that data is transmitted reliably and in order. "
        "Error-checking: Identifies and corrects errors before sending them again."
        "Acknowledgments: Receives acknowledgments from the receiver to ensure delivery of packets."
        "Flow control: Controls the amount of data sent by each side to prevent congestion or overload."
        "Segmentation": Breaks large amounts of data into smaller segments (segments).
      ]
    }
  }
}

{
  "answer": {
    "UDP": {
      "protocol": "User Datagram Protocol",
      "description": "A connectionless protocol that provides low-latency communication, often used for applications requiring quick response times.",
      "key_features": [
        "Connectionless: Unreliable; does not require a full handshake or acknowledgment of packets."
        "No flow control: Does not maintain data packet order or prevent packet loss."
        "Packet loss tolerance: Can handle packet losses without retransmission."
        "Simplicity: Simpler implementation compared to TCP, making it more efficient in terms of CPU usage and bandwidth utilization."
      ]
    }
  }
}
